import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api, { authService } from '../services/api';

const Registro = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [tiposDocumento, setTiposDocumento] = useState([]);
  const [coordinadores, setCoordinadores] = useState([]);
  
  const [formData, setFormData] = useState({
    nombreUsuario: '',
    tipoIdentificacion: '',
    numeroIdentificacion: '',
    nombre: '',
    apellido: '',
    telefono: '',
    correoElectronico: '',
    coordinadorAsignado: '',
    password: '',
    confirmPassword: ''
  });

  useEffect(() => {
    cargarDatosIniciales();
  }, []);

  const cargarDatosIniciales = async () => {
    try {
      const [tiposRes, coordinadoresRes] = await Promise.all([
        api.get('/tipos-documento'),
        api.get('/coordinadores')
      ]);
      setTiposDocumento(tiposRes.data.data || []);
      setCoordinadores(coordinadoresRes.data.data || []);
    } catch (error) {
      console.error('Error cargando datos:', error);
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setLoading(true);

    try {
      if (!formData.nombreUsuario) throw new Error('El nombre de usuario es obligatorio');
      if (!formData.tipoIdentificacion) throw new Error('Seleccione un tipo de identificación');
      if (!formData.numeroIdentificacion) throw new Error('El número de identificación es obligatorio');
      if (!formData.nombre) throw new Error('El nombre es obligatorio');
      if (!formData.apellido) throw new Error('El apellido es obligatorio');
      if (!formData.telefono) throw new Error('El teléfono es obligatorio');
      if (!formData.correoElectronico) throw new Error('El correo es obligatorio');
      if (!formData.coordinadorAsignado) throw new Error('Seleccione un coordinador');
      if (!formData.password) throw new Error('La contraseña es obligatoria');
      if (formData.password !== formData.confirmPassword) throw new Error('Las contraseñas no coinciden');
      if (formData.password.length < 6) throw new Error('La contraseña debe tener al menos 6 caracteres');

      const emailRegex = /^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/;
      if (!emailRegex.test(formData.correoElectronico)) throw new Error('Correo electrónico inválido');

      const { confirmPassword, ...datosEnvio } = formData;
      await api.post('/auth/register', datosEnvio);
      
      setSuccess('✅ ¡Registro exitoso! Redirigiendo al login...');
      setTimeout(() => navigate('/login'), 2000);
    } catch (error) {
      console.error('Error:', error);
      setError(error.response?.data?.message || error.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <style>
        {`
          * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
          }
          body {
            font-family: 'Segoe UI', 'Roboto', 'Helvetica Neue', sans-serif;
          }
          .registro-container {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: linear-gradient(135deg, #e8f5e9 0%, #c8e6d9 100%);
            padding: 30px 20px;
          }
          .registro-card {
            background: white;
            border-radius: 40px;
            padding: 40px 36px;
            width: 100%;
            max-width: 780px;
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08), 0 8px 20px rgba(0, 100, 60, 0.1);
            transition: transform 0.2s ease, box-shadow 0.2s ease;
          }
          .registro-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 28px 48px rgba(0, 0, 0, 0.12), 0 12px 28px rgba(0, 100, 60, 0.15);
          }
          .logo-wrapper {
            text-align: center;
            margin-bottom: 20px;
          }
          .logo {
            width: 100px;
            height: auto;
            filter: drop-shadow(0 4px 6px rgba(0,0,0,0.05));
          }
          .title {
            text-align: center;
            color: #00643C;
            font-size: 28px;
            font-weight: 700;
            margin-bottom: 6px;
            letter-spacing: -0.3px;
          }
          .subtitle {
            text-align: center;
            color: #5a6e7c;
            font-size: 15px;
            margin-bottom: 32px;
            font-weight: 500;
          }
          .error-alert {
            background-color: #ffebee;
            border-left: 4px solid #d32f2f;
            color: #b71c1c;
            padding: 12px 18px;
            border-radius: 20px;
            margin-bottom: 28px;
            font-size: 14px;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 10px;
          }
          .error-alert::before {
            content: "⚠️";
            font-size: 18px;
          }
          .success-alert {
            background-color: #e8f5e9;
            border-left: 4px solid #2e7d32;
            color: #1b5e20;
            padding: 12px 18px;
            border-radius: 20px;
            margin-bottom: 28px;
            font-size: 14px;
            font-weight: 500;
            display: flex;
            align-items: center;
            gap: 10px;
          }
          .success-alert::before {
            content: "✅";
            font-size: 18px;
          }
          .form-grid {
            display: flex;
            flex-direction: column;
            gap: 20px;
          }
          .row {
            display: flex;
            gap: 20px;
            flex-wrap: wrap;
          }
          .half {
            flex: 1;
            min-width: 180px;
          }
          .full {
            width: 100%;
          }
          .input-group {
            display: flex;
            flex-direction: column;
            gap: 6px;
          }
          .label {
            font-size: 13px;
            font-weight: 600;
            color: #1e2a3e;
            letter-spacing: 0.3px;
          }
          .input-icon-wrapper {
            position: relative;
            display: flex;
            align-items: center;
          }
          .input-icon {
            position: absolute;
            left: 16px;
            color: #9aa6b5;
            font-size: 18px;
            pointer-events: none;
          }
          .input-field, .select-field {
            width: 100%;
            padding: 12px 16px 12px 48px;
            border: 1.5px solid #e2e8f0;
            border-radius: 30px;
            font-size: 14px;
            font-family: inherit;
            transition: all 0.2s ease;
            background-color: #fefefe;
            outline: none;
          }
          .input-field:focus, .select-field:focus {
            border-color: #00643C;
            box-shadow: 0 0 0 3px rgba(0, 100, 60, 0.2);
            background-color: #fff;
          }
          .button-group {
            display: flex;
            gap: 16px;
            margin-top: 24px;
            flex-wrap: wrap;
          }
          .btn-primary {
            flex: 1;
            background-color: #00643C;
            color: white;
            padding: 14px 12px;
            border: none;
            border-radius: 40px;
            font-size: 16px;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.2s ease;
            box-shadow: 0 2px 6px rgba(0, 100, 60, 0.2);
            letter-spacing: 0.5px;
          }
          .btn-primary:hover:not(:disabled) {
            background-color: #004d2e;
            transform: translateY(-1px);
            box-shadow: 0 8px 18px rgba(0, 100, 60, 0.25);
          }
          .btn-primary:active:not(:disabled) {
            transform: translateY(1px);
          }
          .btn-primary:disabled {
            background-color: #9bb7a8;
            cursor: not-allowed;
            transform: none;
          }
          .btn-secondary {
            flex: 1;
            background-color: transparent;
            border: 1.5px solid #00643C;
            color: #00643C;
            padding: 12px 12px;
            border-radius: 40px;
            font-size: 16px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s ease;
          }
          .btn-secondary:hover {
            background-color: rgba(0, 100, 60, 0.08);
            border-color: #004d2e;
            color: #004d2e;
          }
          @media (max-width: 680px) {
            .registro-card {
              padding: 30px 20px;
            }
            .row {
              flex-direction: column;
              gap: 16px;
            }
            .half {
              width: 100%;
            }
            .button-group {
              flex-direction: column;
            }
          }
        `}
      </style>

      <div className="registro-container">
        <div className="registro-card">
          <div className="logo-wrapper">
            <img src="/logosena.png" alt="Logo SENA" className="logo" />
          </div>
          <h2 className="title">Gestionytics</h2>
          <p className="subtitle">Crear cuenta nueva</p>

          {error && <div className="error-alert">{error}</div>}
          {success && <div className="success-alert">{success}</div>}

          <form onSubmit={handleSubmit}>
            <div className="form-grid">
              {/* Fila 1: Nombre usuario + Tipo identificación */}
              <div className="row">
                <div className="half">
                  <div className="input-group">
                    <label className="label">Nombre de Usuario</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">👤</span>
                      <input
                        type="text"
                        name="nombreUsuario"
                        value={formData.nombreUsuario}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="ej: juan.perez"
                        required
                      />
                    </div>
                  </div>
                </div>
                <div className="half">
                  <div className="input-group">
                    <label className="label">Tipo Identificación</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">📄</span>
                      <select
                        name="tipoIdentificacion"
                        value={formData.tipoIdentificacion}
                        onChange={handleChange}
                        className="select-field"
                        required
                      >
                        <option value="">Seleccione...</option>
                        {tiposDocumento.map(tipo => (
                          <option key={tipo._id} value={tipo._id}>{tipo.nombre}</option>
                        ))}
                      </select>
                    </div>
                  </div>
                </div>
              </div>

              {/* Fila 2: Número identificación + Teléfono */}
              <div className="row">
                <div className="half">
                  <div className="input-group">
                    <label className="label">Número Identificación</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">🔢</span>
                      <input
                        type="text"
                        name="numeroIdentificacion"
                        value={formData.numeroIdentificacion}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="123456789"
                        required
                      />
                    </div>
                  </div>
                </div>
                <div className="half">
                  <div className="input-group">
                    <label className="label">Teléfono</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">📞</span>
                      <input
                        type="tel"
                        name="telefono"
                        value={formData.telefono}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="3001234567"
                        required
                      />
                    </div>
                  </div>
                </div>
              </div>

              {/* Fila 3: Nombres + Apellidos */}
              <div className="row">
                <div className="half">
                  <div className="input-group">
                    <label className="label">Nombres</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">✍️</span>
                      <input
                        type="text"
                        name="nombre"
                        value={formData.nombre}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="Juan Carlos"
                        required
                      />
                    </div>
                  </div>
                </div>
                <div className="half">
                  <div className="input-group">
                    <label className="label">Apellidos</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">📛</span>
                      <input
                        type="text"
                        name="apellido"
                        value={formData.apellido}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="Pérez González"
                        required
                      />
                    </div>
                  </div>
                </div>
              </div>

              {/* Correo electrónico */}
              <div className="full">
                <div className="input-group">
                  <label className="label">Correo Electrónico</label>
                  <div className="input-icon-wrapper">
                    <span className="input-icon">📧</span>
                    <input
                      type="email"
                      name="correoElectronico"
                      value={formData.correoElectronico}
                      onChange={handleChange}
                      className="input-field"
                      placeholder="ejemplo@correo.com"
                      required
                    />
                  </div>
                </div>
              </div>

              {/* Coordinador Asignado */}
              <div className="full">
                <div className="input-group">
                  <label className="label">Coordinador Asignado</label>
                  <div className="input-icon-wrapper">
                    <span className="input-icon">👨‍🏫</span>
                    <select
                      name="coordinadorAsignado"
                      value={formData.coordinadorAsignado}
                      onChange={handleChange}
                      className="select-field"
                      required
                    >
                      <option value="">Seleccione un coordinador...</option>
                      {coordinadores.map(coord => (
                        <option key={coord._id} value={coord._id}>{coord.nombre}</option>
                      ))}
                    </select>
                  </div>
                </div>
              </div>

              {/* Contraseña y confirmación */}
              <div className="row">
                <div className="half">
                  <div className="input-group">
                    <label className="label">Contraseña</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">🔒</span>
                      <input
                        type="password"
                        name="password"
                        value={formData.password}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="********"
                        required
                      />
                    </div>
                  </div>
                </div>
                <div className="half">
                  <div className="input-group">
                    <label className="label">Confirmar Contraseña</label>
                    <div className="input-icon-wrapper">
                      <span className="input-icon">✔️</span>
                      <input
                        type="password"
                        name="confirmPassword"
                        value={formData.confirmPassword}
                        onChange={handleChange}
                        className="input-field"
                        placeholder="********"
                        required
                      />
                    </div>
                  </div>
                </div>
              </div>

              <div className="button-group">
                <button type="submit" disabled={loading} className="btn-primary">
                  {loading ? 'Registrando...' : 'Registrarse'}
                </button>
                <button type="button" onClick={() => navigate('/login')} className="btn-secondary">
                  Volver al Login
                </button>
              </div>
            </div>
          </form>
        </div>
      </div>
    </>
  );
};

export default Registro;
